public class ParserEdades {
    public static int parsearEdad(String input) {
        int edad;
        try {
            edad = Integer.parseInt(input);
        } catch (NumberFormatException e) {
            throw new NumberFormatException("Entrada no válida: " + input);
        }
        if (edad < 0) {
            throw new IllegalArgumentException("La edad no puede ser negativa");
        }
        return edad;
    }

    public static void main(String[] args) {
        String[] entradas = {"25", "abc", "-5", "30"};
        for (String entrada : entradas) {
            try {
                int edad = parsearEdad(entrada);
                System.out.println("Edad: " + edad);
            } catch (Exception e) {
                System.out.println("Error: " + e.getMessage());
            }
        }
    }
}

