solution:
public class Validar {
    public static void validarNombre(String nombre) {
        if (nombre == null || nombre.isEmpty()) {
            throw new IllegalArgumentException("El nombre no puede ser null o vacío");
        }
    }

    public static void validarEdad(int edad) {
        if (edad < 0 || edad > 150) {
            throw new IndexOutOfBoundsException("La edad debe estar entre 0 y 150");
        }
    }

    public static void validarEmail(String email) {
        if (email == null) {
            throw new NullPointerException("El email no puede ser null");
        }
        if (!email.contains("@")) {
            throw new ArithmeticException("El email debe contener '@'");
        }
    }

    public static void validarTodo(String nombre, int edad, String email) {
        try {
            validarNombre(nombre);
        } catch (IllegalArgumentException e) {
            System.out.println("Error de nombre: " + e.getMessage());
        }
        try {
            validarEdad(edad);
        } catch (IndexOutOfBoundsException e) {
            System.out.println("Error de edad: " + e.getMessage());
        }
        try {
            validarEmail(email);
        } catch (NullPointerException e) {
            System.out.println("Error de email: " + e.getMessage());
        } catch (ArithmeticException e) {
            System.out.println("Error de email: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        validarTodo("", 200, "test");
        System.out.println("---");
        validarTodo("Ana", 25, "ana@mail.com");
    }
}
